CREATE OR REPLACE FUNCTION public.pm_quote_external_line_fee(_item uuid) RETURNS numeric LANGUAGE sql STABLE SET search_path=public AS $$ SELECT coalesce(e.sale_price,0)*coalesce(e.quantity,1)*(1+coalesce((SELECT m.markup_pct FROM quote_supplier_markups m WHERE m.quote_id=e.quote_id AND (m.supplier_company_id=e.supplier_company_id OR (m.supplier_company_id IS NULL AND m.supplier_id=e.supplier_id) OR (m.supplier_company_id IS NULL AND m.supplier_id IS NULL AND lower(trim(m.supplier_label))=lower(trim(e.description)))) ORDER BY CASE WHEN m.supplier_company_id IS NOT NULL THEN 0 WHEN m.supplier_id IS NOT NULL THEN 1 ELSE 2 END,m.id LIMIT 1),0)/100)*coalesce(nullif(q.pricing_multiplier,0),1) FROM quote_external_services e JOIN fee_proposals q ON q.id=e.quote_id WHERE e.id=_item $$;
CREATE OR REPLACE FUNCTION public.pm_quote_stage_billing_fee(_stage uuid) RETURNS numeric LANGUAGE plpgsql STABLE SET search_path=public AS $$ DECLARE s quote_stages; q fee_proposals; derived numeric; child_sum numeric; supplier_sum numeric; m numeric; BEGIN SELECT * INTO s FROM quote_stages WHERE id=_stage; IF NOT FOUND OR coalesce(s.stage_role,'')='client' THEN RETURN 0; END IF; SELECT * INTO q FROM fee_proposals WHERE id=s.quote_id; m:=coalesce(nullif(q.pricing_multiplier,0),1); IF EXISTS(SELECT 1 FROM quote_stages WHERE parent_stage_id=s.id) THEN SELECT coalesce(sum(pm_quote_stage_billing_fee(c.id)),0),coalesce(sum(pm_quote_stage_billing_fee(c.id)) FILTER(WHERE c.stage_role IN('supplier_group','supplier_phase')),0) INTO child_sum,supplier_sum FROM quote_stages c WHERE c.parent_stage_id=s.id; IF s.budget_mode='fixed' THEN RETURN coalesce(s.budget,0)*m+CASE WHEN s.stage_role IN('supplier_group','supplier_phase') THEN 0 ELSE supplier_sum END; END IF; RETURN child_sum+CASE WHEN coalesce(s.stage_role,'architecture') NOT IN('supplier_group','supplier_phase') AND EXISTS(SELECT 1 FROM quote_stages WHERE parent_stage_id=s.id AND stage_role IN('supplier_group','supplier_phase')) THEN coalesce(s.budget,0)*m ELSE 0 END; END IF; SELECT coalesce(sum((pm_relative_offset(a.end_date)-pm_relative_offset(a.start_date)+1)*a.hours_per_day*a.sale_rate_snapshot),0)*m INTO derived FROM quote_allocations a WHERE a.stage_id=s.id; derived:=derived+coalesce((SELECT sum(pm_quote_external_line_fee(e.id)) FROM quote_external_services e WHERE e.stage_id=s.id),0); IF s.budget_mode='fixed' THEN RETURN coalesce(nullif(s.budget,0)*m,derived); END IF; RETURN CASE WHEN derived>0 THEN derived ELSE coalesce(s.budget,0)*m END; END $$;
CREATE OR REPLACE FUNCTION public.pm_quote_payment_amount(_quote uuid,_item uuid,_total numeric) RETURNS numeric LANGUAGE sql STABLE SET search_path=public AS $$ SELECT CASE WHEN p.amount_type::text='fixed' THEN p.amount_value ELSE (CASE WHEN p.trigger_type::text IN('stage_start','stage_end') AND p.stage_id IS NOT NULL THEN public.pm_quote_stage_billing_fee(p.stage_id) ELSE _total END)*p.amount_value/100 END FROM quote_payment_schedule_items p WHERE p.id=_item AND p.quote_id=_quote $$;
CREATE OR REPLACE FUNCTION public.pm_quote_conversion_totals(_quote uuid) RETURNS jsonb LANGUAGE plpgsql STABLE SET search_path=public AS $$ DECLARE q fee_proposals; internal_fee numeric; external_fee numeric; m numeric; monthly numeric; BEGIN SELECT * INTO q FROM fee_proposals WHERE id=_quote; m:=coalesce(nullif(q.pricing_multiplier,0),1); internal_fee:=coalesce(pm_quote_internal_fee(_quote),0); external_fee:=coalesce(pm_quote_external_fee(_quote),0); IF internal_fee=0 AND q.time_based_settings->>'kind'='consultancy_hours_package' THEN internal_fee:=coalesce((q.time_based_settings->>'hourly_rate')::numeric,0)*coalesce((q.time_based_settings->>'hours_block')::numeric,0)*m; ELSIF internal_fee=0 AND q.time_based_settings->>'kind'='construction_retainer' THEN SELECT coalesce(sum((r->>'hours_per_month')::numeric*(r->>'hourly_rate')::numeric),0) INTO monthly FROM jsonb_array_elements(coalesce(q.time_based_settings->'monthly_resources','[]'::jsonb)) r; IF monthly<=0 THEN monthly:=coalesce((q.time_based_settings->>'monthly_estimate')::numeric,0); END IF; internal_fee:=monthly*greatest(1,coalesce((q.time_based_settings->>'construction_duration_months')::integer,1))*m; END IF; RETURN jsonb_build_object('internal_fee',internal_fee,'external_fee',external_fee,'total_fee',internal_fee+external_fee); END $$;
CREATE OR REPLACE FUNCTION public.pm_quote_preview_payment_date(_quote uuid,_start date,_item uuid,_stages jsonb,_payment boolean DEFAULT false) RETURNS date LANGUAGE plpgsql STABLE SET search_path=public AS $$ DECLARE p quote_payment_schedule_items; original date; mapped date; stage_row jsonb; original_start date; BEGIN SELECT * INTO p FROM quote_payment_schedule_items WHERE id=_item AND quote_id=_quote; original:=CASE WHEN _payment THEN p.expected_payment_date ELSE p.expected_invoice_date END; IF coalesce(p.manual_override,false) OR p.trigger_type::text='manual_date' THEN RETURN original; END IF; SELECT value INTO stage_row FROM jsonb_array_elements(_stages) WHERE value->>'id'=p.stage_id::text; IF p.trigger_type::text='project_start' THEN mapped:=_start; ELSIF p.trigger_type::text='stage_start' THEN mapped:=(stage_row->>'start_date')::date; ELSIF p.trigger_type::text='stage_end' THEN mapped:=(stage_row->>'end_date')::date; ELSIF p.trigger_type::text='monthly' AND original IS NOT NULL THEN SELECT min((value->>'start_date')::date) INTO original_start FROM quote_relative_schedules r CROSS JOIN LATERAL jsonb_array_elements(r.original_dates->'stages') WHERE r.quote_id=_quote; original_start:=coalesce(original_start,(SELECT min(start_date) FROM quote_stages WHERE quote_id=_quote)); mapped:=(date_trunc('month',_start)+make_interval(months=>((extract(year FROM original)-extract(year FROM original_start))*12+extract(month FROM original)-extract(month FROM original_start))::integer))::date; ELSE mapped:=pm_quote_payment_date(_quote,_start,original,false); END IF; IF _payment THEN RETURN mapped+coalesce(p.payment_offset_days,coalesce(p.expected_payment_date-p.expected_invoice_date,0)); END IF; RETURN mapped; END $$;
REVOKE ALL ON FUNCTION public.pm_quote_external_line_fee(uuid),public.pm_quote_stage_billing_fee(uuid),public.pm_quote_conversion_totals(uuid),public.pm_quote_preview_payment_date(uuid,date,uuid,jsonb,boolean) FROM PUBLIC,anon,authenticated;
CREATE OR REPLACE FUNCTION public.pm_quote_conversion_preview(_quote uuid,_start date) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE state jsonb; start_day date; dates jsonb; allocations jsonb; payments jsonb; totals jsonb; revision_data jsonb; BEGIN IF auth.uid() IS NULL OR NOT is_psa_staff() THEN RAISE EXCEPTION 'Forbidden' USING ERRCODE='42501'; END IF; IF _start IS NULL THEN RAISE EXCEPTION 'gantt.schedule.invalidRange'; END IF; state:=pm_gantt_state('quote',_quote); start_day:=pm_calendar_shift(_start,0); IF NOT EXISTS(SELECT 1 FROM fee_proposals WHERE id=_quote AND pm_project_id IS NULL) THEN RAISE EXCEPTION 'gantt.schedule.locked'; END IF; IF NOT EXISTS(SELECT 1 FROM quote_relative_schedules WHERE quote_id=_quote) THEN RAISE EXCEPTION 'gantt.relative.required'; END IF; SELECT coalesce(jsonb_agg(jsonb_build_object('id',s.id,'name',s.name,'parent_stage_id',s.parent_stage_id,'start_date',CASE WHEN s.stage_kind='retainer_monthly' THEN date_trunc('month',pm_calendar_shift(start_day,pm_relative_offset(s.start_date)))::date ELSE pm_calendar_shift(start_day,pm_relative_offset(s.start_date)) END,'end_date',CASE WHEN s.stage_kind='retainer_monthly' THEN (date_trunc('month',pm_calendar_shift(start_day,pm_relative_offset(s.start_date)))+make_interval(months=>greatest(1,coalesce(s.retainer_months,1)))-interval '1 day')::date ELSE pm_calendar_shift(start_day,pm_relative_offset(s.end_date)) END,'stage_kind',s.stage_kind,'retainer_months',s.retainer_months,'retainer_monthly_amount',s.retainer_monthly_amount) ORDER BY s.sort_order,s.id),'[]'::jsonb) INTO dates FROM quote_stages s WHERE quote_id=_quote; allocations:=pm_quote_calendar_allocations(_quote,start_day); totals:=pm_quote_conversion_totals(_quote); SELECT coalesce(jsonb_agg(jsonb_build_object('id',p.id,'label',p.label,'amount_type',p.amount_type,'amount_value',p.amount_value,'amount',pm_quote_payment_amount(_quote,p.id,(totals->>'total_fee')::numeric),'expected_invoice_date',pm_quote_preview_payment_date(_quote,start_day,p.id,dates,false),'expected_payment_date',pm_quote_preview_payment_date(_quote,start_day,p.id,dates,true)) ORDER BY p.sort_order,p.id),'[]'::jsonb) INTO payments FROM quote_payment_schedule_items p WHERE p.quote_id=_quote; revision_data:=jsonb_build_object('schedule',state->>'revision','payments',coalesce((SELECT jsonb_agg(to_jsonb(p) ORDER BY id) FROM quote_payment_schedule_items p WHERE quote_id=_quote),'[]'::jsonb),'external',coalesce((SELECT jsonb_agg(to_jsonb(e) ORDER BY id) FROM quote_external_services e WHERE quote_id=_quote),'[]'::jsonb),'quote',(SELECT to_jsonb(q) FROM fee_proposals q WHERE id=_quote),'start',start_day,'calendar',coalesce((SELECT jsonb_agg(data ORDER BY data) FROM holidays),'[]'::jsonb),'markups',coalesce((SELECT jsonb_agg(to_jsonb(m) ORDER BY id) FROM quote_supplier_markups m WHERE quote_id=_quote),'[]'::jsonb),'dates',dates,'allocations',allocations,'resolved_payments',payments,'totals',totals); RETURN jsonb_build_object('start_date',start_day,'stages',dates,'allocations',allocations,'payments',payments,'commercial',totals,'dependencies',state->'dependencies','revision',md5(revision_data::text)); END $$;
